# workflow.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/workflow.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "examples": [
    {
      "initial": "pending",
      "machine_ref": "build-spec/state-machines.json#/machines/1",
      "states": [
        "pending",
        "active",
        "blocked",
        "reported",
        "accepted",
        "cancelled"
      ],
      "terminal": [
        "accepted",
        "cancelled"
      ],
      "transitions": [
        {
          "from": "pending",
          "to": "active",
          "writer": "manager"
        }
      ],
      "version": 1,
      "workflow_id": "chd.assignment"
    }
  ],
  "properties": {
    "initial": {
      "minLength": 1,
      "type": "string"
    },
    "machine_ref": {
      "minLength": 1,
      "type": "string"
    },
    "states": {
      "items": {
        "minLength": 1,
        "type": "string"
      },
      "minItems": 1,
      "type": "array"
    },
    "terminal": {
      "items": {
        "minLength": 1,
        "type": "string"
      },
      "type": "array"
    },
    "transitions": {
      "items": {
        "additionalProperties": false,
        "properties": {
          "from": {
            "type": "string"
          },
          "requires": {
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "to": {
            "type": "string"
          },
          "writer": {
            "type": "string"
          }
        },
        "required": [
          "from",
          "to",
          "writer"
        ],
        "type": "object"
      },
      "type": "array"
    },
    "version": {
      "minimum": 1,
      "type": "integer"
    },
    "workflow_id": {
      "pattern": "^[a-z][a-z0-9._-]+$",
      "type": "string"
    }
  },
  "required": [
    "workflow_id",
    "version",
    "machine_ref",
    "initial",
    "states",
    "terminal",
    "transitions"
  ],
  "title": "CHD WorkflowDefinition",
  "type": "object"
}
```
